{
  "technical_and_design_decisions": [
    "Treat the increment as a change to the existing Spring XD repository rather than a new Spring Framework implementation.",
    "Preserve the existing Gradle build, module conventions, Kafka integration approach, and configuration formats unless a change is required by a user story.",
    "Use the existing Spark and Scala versions already defined by the repository; do not perform a broad dependency or platform upgrade.",
    "Implement Kafka test support so the broker is started and managed as an external process or supplied through an externally configured broker endpoint, rather than embedded in the test JVM.",
    "Use the central dependencies.properties file as the authoritative source for dependency versions referenced by publish-maven.gradle.",
    "Update the container logging pattern to include a date and time while preserving the existing logging backend and log levels.",
    "Treat Sonar violations individually, fixing actionable issues and documenting or marking genuinely irrelevant findings as invalid according to the repository's existing Sonar process.",
    "Provide Spark streaming and batch examples using the repository's established deployment and sample-application patterns."
  ],
  "assumptions": [
    "The existing source repository, build environment, CI configuration, and required third-party dependencies are available and generally buildable before the work starts.",
    "The Spark streaming module in U1 already exists and requires packaging, deployment configuration, and verification rather than implementation of a new streaming engine.",
    "U2 requires a wiki Troubleshooting section documenting the recommended 10K ulimit and the supplied too-many-open-files failure; no product code change is required.",
    "U3 requires changing the existing xd-container-logger.properties pattern and adding or updating focused verification; no centralized logging redesign is required.",
    "U4 covers changing Kafka tests to use a separately running Kafka server, including test setup and teardown or connection configuration.",
    "U6 covers enabling tests to run against a user-provided external Kafka broker, including configuration and documentation, and is estimated separately from the process-based test harness work in U4.",
    "U7 covers the current set of Sonar findings visible in the repository at the start of the work; a large-scale refactoring campaign is out of scope.",
    "U8 requires one representative Spark batch job sample with build, packaging, deployment instructions, and a basic execution or verification path.",
    "One workday represents one developer working day, and estimates include implementation and focused developer testing but exclude elapsed waiting time for external reviews or infrastructure provisioning."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository assessment and increment planning",
      "activity_description": "Inspect the existing Spring XD modules, Gradle scripts, Spark and Kafka integrations, logging configuration, documentation structure, test conventions, and Sonar configuration; identify affected files and establish a local verification plan.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A2",
      "activity_name": "Scala Spark streaming deployment support",
      "activity_description": "Complete or adjust the Scala Spark streaming module packaging, deployment metadata, runtime configuration, and sample usage so that a Scala developer can deploy it through the existing Spring XD mechanism; add focused deployment and configuration tests.",
      "most_likely_effort": 8.0
    },
    {
      "activity_id": "A3",
      "activity_name": "ulimit troubleshooting documentation",
      "activity_description": "Add the new wiki Troubleshooting section documenting the recommended 10K ulimit setting, explain why it prevents the too-many-open-files deployment failure, and include the relevant configuration or verification commands.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A4",
      "activity_name": "Timestamp inclusion in container logs",
      "activity_description": "Update xd-container-logger.properties so log entries include the date and time, verify the resulting format with the existing logging configuration, and update focused configuration or regression tests if present.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A5",
      "activity_name": "Kafka tests with a separate broker process",
      "activity_description": "Refactor Kafka test infrastructure to connect to a Kafka server running outside the test JVM, implement suitable local test process lifecycle or startup configuration, remove dependence on an embedded broker where applicable, and verify affected test suites.",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "A6",
      "activity_name": "Kafka tests against an externally supplied broker",
      "activity_description": "Add configuration and test execution support for a broker supplied outside the build process, including broker endpoint and availability handling, documented invocation, and a mode that avoids provisioning Kafka as part of the build.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A7",
      "activity_name": "Centralize publish-maven dependency versions",
      "activity_description": "Modify publish-maven.gradle to read Spring Boot, hadoop-common, and other applicable dependency versions from dependencies.properties, remove duplicated literals, handle Gradle property loading consistently, and verify publishing-script behavior.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A8",
      "activity_name": "Sonar violation review and remediation",
      "activity_description": "Run or inspect the current Sonar report, classify findings, fix relevant violations, update irrelevant findings as invalid using the established project conventions, and rerun quality checks to confirm the resulting status.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "A9",
      "activity_name": "Spark batch job sample",
      "activity_description": "Create a representative Spark batch job sample, including source code, build and packaging configuration, deployment metadata, example input/output or execution instructions, and a basic build and execution verification.",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "A10",
      "activity_name": "Cross-feature integration testing and build verification",
      "activity_description": "Run the relevant unit, integration, Spark, Kafka, packaging, and documentation checks; diagnose and correct integration regressions caused by the increment; verify clean builds in the supported local configurations.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A11",
      "activity_name": "Final documentation, change review, and delivery preparation",
      "activity_description": "Review configuration and operational documentation for consistency, update developer-facing usage instructions, prepare release notes or change summaries, and perform a final source and build sanity review.",
      "most_likely_effort": 2.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 43.0
  }
}

